package io.github.diodeme.ji.security.oauth;

import java.net.URI;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;

/** Provider-published OAuth endpoints and callbacks approved during client registration. */
public record OAuthProviderMetadata(
        String provider,
        URI authorizationEndpoint,
        URI tokenEndpoint,
        Optional<URI> deviceAuthorizationEndpoint,
        Set<URI> registeredHttpsCallbacks) {
    public OAuthProviderMetadata {
        if (provider == null || provider.isBlank()) throw new IllegalArgumentException("provider must not be blank");
        requireHttps(authorizationEndpoint, "authorizationEndpoint");
        requireHttps(tokenEndpoint, "tokenEndpoint");
        deviceAuthorizationEndpoint = deviceAuthorizationEndpoint == null ? Optional.empty() : deviceAuthorizationEndpoint;
        deviceAuthorizationEndpoint.ifPresent(value -> requireHttps(value, "deviceAuthorizationEndpoint"));
        registeredHttpsCallbacks = Set.copyOf(Objects.requireNonNull(registeredHttpsCallbacks, "registeredHttpsCallbacks"));
        registeredHttpsCallbacks.forEach(value -> requireHttps(value, "registeredHttpsCallback"));
    }

    private static void requireHttps(URI uri, String name) {
        Objects.requireNonNull(uri, name);
        if (!"https".equalsIgnoreCase(uri.getScheme())) throw new IllegalArgumentException(name + " must use HTTPS");
    }
}
